const isContainer = (value) => value !== null && typeof value === 'object';
const has = (target, key) => Object.prototype.hasOwnProperty.call(target, key);

function copyWith(container, key, value) {
  if (Array.isArray(container)) {
    const copy = container.slice();
    copy[key] = value;
    return copy;
  }
  const copy = {};
  for (const name of Object.keys(container)) copy[name] = container[name];
  copy[key] = value;
  return copy;
}

function write(current, path, depth, value) {
  const key = path[depth];
  if (Array.isArray(current)) {
    if (typeof key !== 'number') throw new TypeError('a string key cannot address an array');
    if (key > current.length) throw new RangeError('an index past the end of the array');
  } else if (typeof key !== 'string') {
    throw new TypeError('a number key cannot address a plain object');
  }

  const held = current[key];
  const present = Array.isArray(current) ? key < current.length : has(current, key);

  if (depth === path.length - 1) {
    if (present && Object.is(held, value)) return current;
    return copyWith(current, key, value);
  }

  const child = isContainer(held)
    ? held
    : (typeof path[depth + 1] === 'number' ? [] : {});
  const next = write(child, path, depth + 1, value);
  if (next === child && child === held) return current;
  return copyWith(current, key, next);
}

export function setIn(obj, path, value) {
  if (!Array.isArray(path)) throw new TypeError('path must be an array');
  for (const key of path) {
    const ok = typeof key === 'string'
      || (typeof key === 'number' && Number.isInteger(key) && key >= 0);
    if (!ok) throw new TypeError('every key must be a string or an integer of at least 0');
  }
  if (path.length === 0) return value;
  if (!isContainer(obj)) throw new TypeError('obj must be a plain object or an array');
  return write(obj, path, 0, value);
}
